+#define KVM_HOST_HCALL_REGS(x)						\
+	__KVM_HCALL_MAP(x, __KVM_HCALL_ARGS				\
+		,, cpu_reg(host_ctxt, 1),, cpu_reg(host_ctxt, 2)	\
+		,, cpu_reg(host_ctxt, 3),, cpu_reg(host_ctxt, 4)	\
+		,, cpu_reg(host_ctxt, 5),, cpu_reg(host_ctxt, 6))
